it('renders button and select per requirements', () => {
  const btn = container.querySelector('button[data-part=root]');
  expect(btn).toBeTruthy(); expect(btn.textContent).toBe('提交');
  expect(btn.disabled).toBe(false);
  const sel = container.querySelector('select[data-part=root]');
  expect(sel).toBeTruthy();
  const opts = Array.from(sel.options).map(o => o.value + ':' + o.textContent);
  expect(opts).toContain(':请选择'); expect(opts).toContain('enabled:已启用'); expect(opts).toContain('disabled:已禁用');
});
it('button click fires and select change fires', () => {
  const btn = container.querySelector('button[data-part=root]');
  let clicked = false; btn.addEventListener('click', () => { clicked = true; });
  btn.click(); expect(clicked).toBe(true);
  const sel = container.querySelector('select[data-part=root]');
  let changed = null; sel.addEventListener('change', () => { changed = sel.value; });
  sel.value = 'disabled'; sel.dispatchEvent(new Event('change', { bubbles: true }));
  expect(changed).toBe('disabled');
});
